function addDamageNumber(x,y,value,color='#fff',crit=false,label=''){effects.push({kind:'number',x,y:y-10,value,label,color,crit,life:.72,max:.72})}
function addImpactParticles(x,y,color='#f2d29b',count=5,strong=false){for(let i=0;i<count;i++){const a=rnd(0,Math.PI*2),sp=rnd(strong?45:28,strong?105:72);effects.push({kind:'spark',x,y:y-8,vx:Math.cos(a)*sp,vy:Math.sin(a)*sp*.7-20,color,life:rnd(.22,.42),max:.42})}}
function addShockRing(x,y,color='rgba(255,228,170,.9)',radius=34,strong=false){effects.push({kind:'ring',x,y:y-4,color,radius,life:(strong ? .34 : .24),max:(strong ? .34 : .24),strong})}
function addSlashTrail(x,y,angle,strong=false,combo=1){effects.push({kind:'trail',x,y,angle,size:strong?188:154,life:(strong ? .3 : .22),max:(strong ? .3 : .22),strong,combo});if(strong)effects.push({kind:'trail',x:x-Math.cos(angle)*10,y:y-Math.sin(angle)*8,angle,size:208,life:.22,max:.22,strong:true,combo})}
function addImpactBurst(x,y,color='#ffe7a5',strong=false,crit=false){effects.push({kind:'burst',x,y:y-6,color,life:(strong ? .34 : .25),max:(strong ? .34 : .25),strong,crit});addShockRing(x,y,crit?'rgba(255,212,107,.95)':color,strong?44:30,strong)}
function registerPerfectDodge(p,h){if(h.dodged)return;h.dodged=true;p.stam=clamp(p.stam+8,0,100);addDamageNumber(p.x,p.y,'ESQUIVA!','#8fe8ff',false,'');effects.push({kind:'dash',x:p.x,y:p.y,life:.18,max:.18});gameVibrate(12)}
function damageEnemy(p,e,dmg,{crit=false,strong=false,knock=18,color='#fff'}={}){
  let total=Math.max(1,Math.round(dmg));
  let pack=false,bonus=0;
  if(players.length>1&&e.lastHitBy&&e.lastHitBy!==p.id&&worldClock-(e.lastHitAt||-99)<.36&&worldClock-(e.lastPackAt||-99)>.75){pack=true;bonus=Math.max(1,Math.round(total*.30));total+=bonus;e.lastPackAt=worldClock;}
  e.hp-=total;e.flash=strong?.22:.16;e.state='aggro';
  e.lastHitBy=p.id;e.lastHitAt=worldClock;
  e.x+=p.dirX*knock;e.y+=p.dirY*knock;
  addDamageNumber(e.x,e.y,total,crit?'#ffd36b':color,crit);
  if(crit)addDamageNumber(e.x,e.y-18,'CRIT','#ffe08a',true);
  addImpactParticles(e.x,e.y,crit?'#ffd36b':'#f0d8b0',strong?9:(crit?7:5),strong||crit);
  addImpactBurst(e.x,e.y,crit?'rgba(255,214,110,.92)':'rgba(240,216,176,.82)',strong,crit);
  if(pack)addDamageNumber(e.x,e.y-34,'MANADA! +'+bonus,'#8fe8ff',true);
  triggerHitStop((strong||crit) ? .048 : .028);if(strong||crit||pack)triggerShake(strong?4.6:(crit?3.5:2.6));
  if(strong||crit||pack)gameVibrate(pack?[18,18,28]:(strong?[24,18,28]:18));
  AudioManager.play(crit||pack?'crit':'hit');
  return total;
}

// ---------------------------
// Procedural classic-RPG SFX (WebAudio, no external audio files)
// ---------------------------
const AudioManager = (() => {
  let ac = null, master = null;
  const ensure = () => {
    if(!ac){
      const Ctx = window.AudioContext || window.webkitAudioContext;
      if(!Ctx) return null;
      ac = new Ctx();
      master = ac.createGain();
      master.gain.value = 0.16;
      master.connect(ac.destination);
    }
    if(ac.state === 'suspended') ac.resume().catch(()=>{});
    return ac;
  };
  const tone = (freq=440,dur=.08,type='square',vol=.12,delay=0,endFreq=null) => {
    const c=ensure(); if(!c)return;
    const t=c.currentTime+delay, o=c.createOscillator(), g=c.createGain();
    o.type=type; o.frequency.setValueAtTime(freq,t);
    if(endFreq) o.frequency.exponentialRampToValueAtTime(Math.max(1,endFreq),t+dur);
    g.gain.setValueAtTime(0.0001,t);
    g.gain.exponentialRampToValueAtTime(Math.max(.0002,vol),t+.008);
    g.gain.exponentialRampToValueAtTime(.0001,t+dur);
    o.connect(g); g.connect(master); o.start(t); o.stop(t+dur+.015);
  };
  const noise = (dur=.06,vol=.08,delay=0,cut=1400) => {
    const c=ensure(); if(!c)return;
    const len=Math.max(1,Math.floor(c.sampleRate*dur)), buf=c.createBuffer(1,len,c.sampleRate), data=buf.getChannelData(0);
    for(let i=0;i<len;i++) data[i]=(Math.random()*2-1)*(1-i/len);
    const src=c.createBufferSource(), filter=c.createBiquadFilter(), g=c.createGain(), t=c.currentTime+delay;
    filter.type='lowpass'; filter.frequency.value=cut; g.gain.setValueAtTime(vol,t); g.gain.exponentialRampToValueAtTime(.0001,t+dur);
    src.buffer=buf; src.connect(filter); filter.connect(g); g.connect(master); src.start(t);
  };
  const play = name => {
    switch(name){
      case 'dialog': tone(720,.035,'square',.045); break;
      case 'uiOpen': tone(420,.045,'triangle',.05); tone(620,.05,'triangle',.04,.035); break;
      case 'uiClose': tone(520,.045,'triangle',.045); tone(330,.055,'triangle',.04,.035); break;
      case 'attack': noise(.045,.055,0,1900); tone(180,.055,'sawtooth',.04,0,110); break;
      case 'hit': noise(.065,.085,0,900); tone(105,.07,'square',.055); break;
      case 'crit': noise(.08,.1,0,1700); tone(210,.07,'square',.07); tone(420,.08,'triangle',.045,.025); break;
      case 'dash': noise(.09,.035,0,2600); tone(190,.12,'sine',.045,0,620); break;
      case 'skill': tone(220,.13,'triangle',.05); tone(330,.14,'triangle',.045,.055); tone(495,.17,'triangle',.04,.11); break;
      case 'chest': tone(392,.08,'square',.045); tone(523,.08,'square',.045,.08); tone(659,.12,'triangle',.05,.16); break;
      case 'pickup': tone(660,.055,'square',.04); tone(880,.08,'triangle',.045,.05); break;
      case 'coin': tone(988,.045,'square',.035); tone(1318,.06,'square',.03,.04); break;
      case 'level': [523,659,784,1047].forEach((f,i)=>tone(f,.11,'triangle',.05,i*.075)); break;
      case 'heal': [440,554,659,880].forEach((f,i)=>tone(f,.16,'sine',.035,i*.07)); break;
      case 'quest': tone(440,.07,'triangle',.04); tone(660,.09,'triangle',.045,.07); tone(880,.11,'triangle',.04,.14); break;
    }
  };
  return { unlock: ensure, play };
})();

