// Assets + temporary chroma fallback
// ---------------------------
function maybeChromaKey(key, img){
  if(!CHROMA_CANDIDATES.has(key)) return img;
  const oc = document.createElement('canvas'); oc.width=img.naturalWidth; oc.height=img.naturalHeight;
  const octx=oc.getContext('2d',{willReadFrequently:true}); octx.imageSmoothingEnabled=false; octx.drawImage(img,0,0);
  let data;
  try{ data=octx.getImageData(0,0,oc.width,oc.height); }catch{ return img; }
  const px=data.data, total=oc.width*oc.height;
  let transparent=0;
  for(let i=3;i<px.length;i+=4) if(px[i]<16) transparent++;
  if(transparent/total > .015) return img; // native transparency already present: do nothing
  const samples=[[0,0],[oc.width-1,0],[0,oc.height-1],[oc.width-1,oc.height-1]].map(([x,y])=>{const i=(y*oc.width+x)*4;return [px[i],px[i+1],px[i+2]]});
  const bg=samples.reduce((a,c)=>[a[0]+c[0]/4,a[1]+c[1]/4,a[2]+c[2]/4],[0,0,0]);
  let similar=true;
  for(const s of samples){ if(Math.hypot(s[0]-bg[0],s[1]-bg[1],s[2]-bg[2])>26) similar=false; }
  if(!similar) return img;
  for(let i=0;i<px.length;i+=4){
    const d=Math.hypot(px[i]-bg[0],px[i+1]-bg[1],px[i+2]-bg[2]);
    if(d<28) px[i+3]=0; else if(d<42) px[i+3]=Math.min(px[i+3],Math.round((d-28)/14*255));
  }
  octx.putImageData(data,0,0); return oc;
}
