function npcBehavior(name){return NPC_BEHAVIOR[name]||NPC_BEHAVIOR.default;}
function buildNpcSpriteSheet(src,key){
  if(!src)return null;
  const w=src.width||src.naturalWidth||0,h=src.height||src.naturalHeight||0;
  if(!w||!h)return null;
  const frames=6, sheet=document.createElement('canvas');sheet.width=w*frames;sheet.height=h;
  const sctx=sheet.getContext('2d');sctx.imageSmoothingEnabled=false;
  const meta=NPC_SHEET_META[key]||{accent:'#d1d1d1',trim:'#555'};
  const steps=[
    {topX:0,topY:0,legX:0,legY:0,arm:0,blink:false},
    {topX:-1,topY:-1,legX:2,legY:0,arm:1,blink:false},
    {topX:0,topY:-1,legX:1,legY:0,arm:0,blink:false},
    {topX:1,topY:0,legX:-2,legY:0,arm:-1,blink:false},
    {topX:0,topY:-1,legX:-1,legY:0,arm:0,blink:true},
    {topX:-1,topY:0,legX:1,legY:0,arm:1,blink:false}
  ];
  const split=Math.max(1,Math.floor(h*.58));
  for(let i=0;i<frames;i++){
    const st=steps[i],ox=i*w;
    sctx.globalAlpha=.18;
    for(const [dx,dy] of [[-1,0],[1,0],[0,-1],[0,1]]) sctx.drawImage(src,0,0,w,h,ox+dx,dy,w,h);
    sctx.globalAlpha=1;
    sctx.drawImage(src,0,0,w,split,ox+st.topX,Math.max(0,st.topY),w,split);
    sctx.drawImage(src,0,split,w,h-split,ox+st.legX,split+st.legY,w,h-split);
    sctx.fillStyle='rgba(0,0,0,.16)';
    sctx.fillRect(ox+Math.floor(w*.18),h-4,Math.floor(w*.64),2);
    sctx.fillStyle=meta.accent;
    sctx.fillRect(ox+Math.floor(w*.24),Math.floor(h*.48),Math.floor(w*.52),2);
    sctx.fillStyle=meta.trim;
    sctx.fillRect(ox+Math.floor(w*.22),Math.floor(h*.50),Math.floor(w*.56),1);
    sctx.fillStyle='rgba(255,255,255,.12)';
    sctx.fillRect(ox+Math.floor(w*.25),Math.floor(h*.17),Math.floor(w*.30),1);
    sctx.fillStyle=meta.accent;
    sctx.fillRect(ox+Math.floor(w*.19)+st.arm,Math.floor(h*.34),2,Math.floor(h*.17));
    sctx.fillRect(ox+Math.floor(w*.79)-st.arm,Math.floor(h*.34),2,Math.floor(h*.17));
    sctx.fillStyle='rgba(255,255,255,.16)';
    sctx.fillRect(ox+Math.floor(w*.28),Math.floor(h*.20),Math.floor(w*.18),1);
    if(st.blink){sctx.fillStyle='rgba(44,30,24,.55)';sctx.fillRect(ox+Math.floor(w*.37),Math.floor(h*.25),Math.floor(w*.07),1);sctx.fillRect(ox+Math.floor(w*.56),Math.floor(h*.25),Math.floor(w*.07),1);}
  }
  return sheet;
}
function generateNpcSpriteSheets(){
  ['npc_toto','npc_rufus','npc_barto','npc_mora'].forEach(key=>{
    if(drawAssets[key]&&!drawAssets[key+'_sheet'])drawAssets[key+'_sheet']=buildNpcSpriteSheet(drawAssets[key],key);
  });
}
function drawStripFrame(sheetKey,frameCount,frame,sx,sy,size,flip=false,alpha=1,customCtx=ctx){
  const im=drawAssets[sheetKey];if(!im)return 0;
  const frameW=Math.floor(im.width/frameCount),frameH=im.height,drawH=Math.round(size*frameH/frameW);
  customCtx.save();customCtx.globalAlpha=alpha;customCtx.translate(Math.round(sx),Math.round(sy));if(flip)customCtx.scale(-1,1);
  customCtx.drawImage(im,frame*frameW,0,frameW,frameH,Math.round(-size/2),Math.round(-drawH),Math.round(size),drawH);
  customCtx.restore();
  return drawH;
}
function drawGridFrame(sheetKey,cols,rows,col,row,sx,sy,size,flip=false,alpha=1,customCtx=ctx){
  const im=drawAssets[sheetKey];if(!im)return 0;
  const frameW=Math.floor(im.width/cols),frameH=Math.floor(im.height/rows),drawH=Math.round(size*frameH/frameW);
  const c=((col%cols)+cols)%cols,r=((row%rows)+rows)%rows;
  customCtx.save();customCtx.globalAlpha=alpha;customCtx.translate(Math.round(sx),Math.round(sy));if(flip)customCtx.scale(-1,1);
  customCtx.drawImage(im,c*frameW,r*frameH,frameW,frameH,Math.round(-size/2),Math.round(-drawH),Math.round(size),drawH);
  customCtx.restore();
  return drawH;
}
function npcSheetRow(n){
  const dx=n.dirX||0,dy=n.dirY||0;
  if(Math.abs(dy)>=Math.abs(dx)) return dy>=0?0:1;
  return dx<0?2:3;
}
function loadAssets(){
  return Promise.all(Object.entries(ASSET_PATHS).map(([key,src])=>new Promise(resolve=>{
    const im=new Image(); images[key]=im;
    im.onload=()=>{ loadedAssets++; drawAssets[key]=maybeChromaKey(key,im); resolve(); };
    im.onerror=()=>{ loadedAssets++; drawAssets[key]=null; resolve(); };
    im.src=src;
  })));
}

// ---------------------------
// Responsive fullscreen viewport
// ---------------------------
function resizeGame(){
  dpr = touchMode ? Math.min(2,Math.max(1,Math.floor(window.devicePixelRatio||1))) : 1;
  const vv = window.visualViewport;
  const sw = Math.max(320, Math.round(vv ? vv.width : window.innerWidth));
  const sh = Math.max(240, Math.round(vv ? vv.height : window.innerHeight));
  canvas.width=Math.round(sw*dpr); canvas.height=Math.round(sh*dpr); canvas.style.width=sw+'px'; canvas.style.height=sh+'px';
  ctx.setTransform(dpr,0,0,dpr,0,0); ctx.imageSmoothingEnabled=false;
  viewport.screenW=sw; viewport.screenH=sh;
  viewport.w=Math.min(sw,MAX_VISIBLE_WIDTH); viewport.h=Math.min(sh,MAX_VISIBLE_HEIGHT);
  viewport.x=Math.round((sw-viewport.w)/2); viewport.y=Math.round((sh-viewport.h)/2);
  const worldScale=getWorldRenderScale();
  viewport.worldW=viewport.w/worldScale; viewport.worldH=viewport.h/(PROJECTION_Y*worldScale);
  const mr=minimap.getBoundingClientRect(); minimap.width=Math.max(1,Math.round(mr.width*dpr)); minimap.height=Math.max(1,Math.round(mr.height*dpr));
  mctx.setTransform(dpr,0,0,dpr,0,0); mctx.imageSmoothingEnabled=false;
  clampCamera();
}
window.addEventListener('resize',resizeGame,{passive:true});
if(window.visualViewport) window.visualViewport.addEventListener('resize',resizeGame,{passive:true});

function clampCamera(){
  if(scene==='world' && mapModel){
    const halfW=viewport.worldW/2, halfH=viewport.worldH/2;
    camera.x = mapWidthPx <= viewport.worldW ? mapWidthPx/2 : clamp(camera.x,halfW,mapWidthPx-halfW);
    camera.y = mapHeightPx <= viewport.worldH ? mapHeightPx/2 : clamp(camera.y,halfH,mapHeightPx-halfH);
  } else if(scene==='dungeon'){
    const DW=1800,DH=1200,halfW=viewport.worldW/2,halfH=viewport.worldH/2;
    camera.x=DW<=viewport.worldW?DW/2:clamp(camera.x,halfW,DW-halfW);
    camera.y=DH<=viewport.worldH?DH/2:clamp(camera.y,halfH,DH-halfH);
  } else { camera.x=500; camera.y=350; }
}
function worldToScreen(x,y){ return {x:Math.round(viewport.x+viewport.w/2+(x-camera.x)), y:Math.round(viewport.y+viewport.h/2+(y-camera.y)*PROJECTION_Y)}; }
function currentWorldBounds(pad=0){ return {l:camera.x-viewport.worldW/2-pad,r:camera.x+viewport.worldW/2+pad,t:camera.y-viewport.worldH/2-pad,b:camera.y+viewport.worldH/2+pad}; }
function isVisibleWorld(x,y,pad=120){const b=currentWorldBounds(pad);return x>=b.l&&x<=b.r&&y>=b.t&&y<=b.b;}

