function buildVillageProps(){
  // Beta 0.27: la fuente queda sola. Nada de bancos, faroles, flores,
  // carteles o cercas generadas dentro de la plaza central.
  villageProps=[];
}
function computeVillageVisuals(){
  const villageObjects=mapObjects.filter(o=>o.type==='building'||o.type==='npc');
  if(!villageObjects.length){villageGroundBounds=null;villageCobbleAnchors=[];villagePlaza=null;villageCenterpiece=null;villageProps=[];return;}
  const xs=villageObjects.map(o=>o.x),ys=villageObjects.map(o=>o.y);
  const minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);
  const centerX=(minX+maxX)/2,centerY=(minY+maxY)/2;
  villageGroundBounds={minX:minX-420,maxX:maxX+420,minY:minY-320,maxY:maxY+260,centerX,centerY};
  villageCobbleAnchors=villageObjects.filter(o=>o.type==='building').map(o=>({x:o.x,y:o.y,rx:210,ry:150}));
  villageCobbleAnchors.push({x:centerX,y:centerY,rx:Math.max(260,(maxX-minX)*.46),ry:Math.max(180,(maxY-minY)*.42)});
  villagePlaza={x:centerX,y:centerY+28,rx:Math.max(150,(maxX-minX)*.18),ry:Math.max(110,(maxY-minY)*.14)};
  villageCenterpiece={x:centerX,y:centerY+26,rx:Math.max(54,(maxX-minX)*.045),ry:Math.max(36,(maxY-minY)*.032),label:'Fuente de la Manada'};
  buildVillageProps();
}
function initWorldNpcStates(){
  npcWorldStates=mapObjects.filter(o=>o.type==='npc').map(o=>{
    const behavior=npcBehavior(o.name);
    return {
      id:o.id||o.name,obj:o,x:o.x,y:o.y,originX:o.x,originY:o.y,targetX:o.x,targetY:o.y,
      wait:rnd(.55,1.7),speed:rnd(behavior.speed[0],behavior.speed[1]),anim:rnd(0,4),dirX:0,dirY:1,moving:false,speedNow:0,
      behavior,idleMode:'stand',poseTimer:rnd(.3,1.1),bob:rnd(0,Math.PI*2),routeBias:Math.random()<behavior.plazaBias?'plaza':'home'
    };
  });
}
function isNearFountainVisual(o,extra=0){
  if(!villageCenterpiece||!o)return false;
  return Math.hypot((o.x||0)-villageCenterpiece.x,(o.y||0)-villageCenterpiece.y)<340+extra;
}
function rebuildWorldCollisions(){
  const preserved=mapCollisions.filter(r=>{
    const owner=r.props&&r.props.owner;
    return !['tree','house_toto','forge','inn','elder','cave'].includes(owner);
  });
  const generated=[];
  for(const o of mapObjects.filter(o=>o.type==='building')){
    const w=(o.props.tilesWide||5)*TILE_SIZE;
    const footW=Math.round(w*.78),footH=52;
    generated.push({name:o.name+' footprint',type:'collision',x:o.x-footW/2,y:o.y-footH+8,width:footW,height:footH,props:{owner:o.props.objectId||'building'}});
  }
  for(const o of mapDecor){
    if(o.props&&o.props.solid){
      const sc=o.props.scale||1,tw=Math.round(30*sc),th=Math.round(24*sc);
      generated.push({name:'tree footprint',type:'collision',x:o.x-tw/2,y:o.y-th+3,width:tw,height:th,props:{owner:'tree'}});
    }
    if(o.props&&o.props.asset==='well'&&!isNearFountainVisual(o,40)){
      generated.push({name:'well footprint',type:'collision',x:o.x-34,y:o.y-24,width:68,height:34,props:{owner:'well'}});
    }
  }
  const cave=mapObjects.find(o=>o.type==='cave');
  if(cave)generated.push({name:'cave footprint',type:'collision',x:cave.x-112,y:cave.y-58,width:224,height:54,props:{owner:'cave'}});
  if(villageCenterpiece)generated.push({name:'fountain footprint',type:'collision',x:villageCenterpiece.x-66,y:villageCenterpiece.y-34,width:132,height:44,props:{owner:'fountain'}});
  mapCollisions=[...preserved,...generated];
}
function isInsideTownSafeZone(x,y,pad=0){
  if(!villageGroundBounds)return false;
  return x>=villageGroundBounds.minX-pad&&x<=villageGroundBounds.maxX+pad&&y>=villageGroundBounds.minY-pad&&y<=villageGroundBounds.maxY+pad;
}
function resolveVillageSpawn(){
  if(!villagePlaza||!villageCenterpiece)return;
  const candidates=[
    {x:villagePlaza.x-villagePlaza.rx*.88,y:villagePlaza.y+villagePlaza.ry*.42},
    {x:villagePlaza.x+villagePlaza.rx*.88,y:villagePlaza.y+villagePlaza.ry*.42},
    {x:villagePlaza.x-villagePlaza.rx*.82,y:villagePlaza.y-villagePlaza.ry*.50},
    {x:villagePlaza.x+villagePlaza.rx*.82,y:villagePlaza.y-villagePlaza.ry*.50}
  ];
  for(const c of candidates){
    if(Math.hypot(c.x-villageCenterpiece.x,c.y-villageCenterpiece.y)<190)continue;
    if(!npcPositionBlocked(c.x,c.y,18)){spawnPoint={x:c.x,y:c.y};return;}
  }
  spawnPoint={x:villagePlaza.x-villagePlaza.rx-170,y:villagePlaza.y};
}
function projectEnemySpawnOutsideTown(x,y,margin=170){
  if(!isInsideTownSafeZone(x,y,0))return {x,y};
  const b=villageGroundBounds;
  const sides=[
    {d:Math.abs(x-b.minX),x:b.minX-margin,y},
    {d:Math.abs(b.maxX-x),x:b.maxX+margin,y},
    {d:Math.abs(y-b.minY),x,y:b.minY-margin},
    {d:Math.abs(b.maxY-y),x,y:b.maxY+margin}
  ].sort((a,b)=>a.d-b.d);
  for(const p of sides){if(!npcPositionBlocked(p.x,p.y,22))return {x:p.x,y:p.y};}
  return {x:b.minX-margin,y:b.minY-margin};
}
function applyWorldHotfixes(){
  const cave = mapObjects.find(o=>o.type==='cave');
  if(cave){
    cave.x = 7728;
    cave.y = 4176;
    caveTrigger = { x:cave.x, y:cave.y + 86, width:260, height:118 };
  } else caveTrigger = null;
  computeVillageVisuals();
  rebuildWorldCollisions();
  resolveVillageSpawn();
  initWorldNpcStates();
}
function loadTiledMap(data){
  mapModel=data; mapWidthPx=data.width*TILE_SIZE; mapHeightPx=data.height*TILE_SIZE; tileLayers=Object.create(null); mapObjects=[];mapDecor=[];mapCollisions=[];
  for(const layer of data.layers){
    if(layer.type==='tilelayer') tileLayers[layer.name]=layer;
    else if(layer.type==='objectgroup'){
      if(layer.name==='objects') mapObjects=layer.objects.map(o=>({...o,props:propMap(o)}));
      if(layer.name==='decoration') mapDecor=layer.objects.map(o=>({...o,props:propMap(o)}));
      if(layer.name==='collision') mapCollisions=layer.objects.map(o=>({...o,props:propMap(o)}));
    }
  }
  const sp=mapObjects.find(o=>o.type==='spawn'); if(sp)spawnPoint={x:sp.x,y:sp.y};
  applyWorldHotfixes();
}
function ensureWorldReady(){
  if(!mapModel || !tileLayers.ground || !mapObjects.length){
    loadTiledMap(EMBEDDED_VILLAGE_MAP);
  }
}

