function makeItem(slot,level=1,forcedTier=null){
  const idx=forcedTier===null?(Math.random()<.05?3:Math.random()<.22?2:Math.random()<.55?1:0):forcedTier;
  const rr=RARITIES[idx]; const names={weapon:['Hueso Tallado','Colmillo Azul','Espada del Sabueso','Mandíbula de Cerbero'],head:['Capucha de Viaje','Casco del Rastreador','Yelmo del Mastín','Corona de Cerbero'],armor:['Arnés de Cuero','Pechera del Pastor','Coraza de Guerra','Armadura del Alfa'],charm:['Collar de Cuero','Medalla de Caza','Collar Rúnico','Collar del Primer Alfa'],boots:['Botas Simples','Botas del Galgo','Grebas de Caza','Pisadas Celestiales'],artifact:['Piedra de Olfato','Tótem de la Manada','Orbe Lunar','Corazón Ancestral']}[slot];
  return {id:Math.random().toString(36).slice(2),slot,tier:idx,rarity:rr.name,color:rr.color,power:Math.round((5+level*2.5)*rr.mult),name:names[Math.min(3,Math.floor(level/3))],asset:ITEM_ASSET[slot]};
}
function makePlayer(id,x,y,name,role,sheet){
  const tank=role==='Guardián';
  const p={kind:'player',id,name,role,sheet,x,y,r:15,level:1,xp:0,next:85,points:1,skills:{power:0,dash:0,howl:0},baseHp:tank?185:130,baseMp:tank?72:96,baseAtk:tank?19:16,baseDef:tank?5:2,baseSpeed:tank?278:325,hp:0,maxHp:0,mp:0,maxMp:0,attack:0,def:0,speed:0,stam:100,dirX:1,dirY:0,state:'idle',anim:0,attackCd:0,dashCd:0,skillCd:0,combo:0,comboTimer:0,inv:0,flash:0,buffs:{inn:0},equip:{head:null,weapon:null,armor:null,charm:null,boots:null,artifact:null},inventory:[]};
  recalc(p); return p;
}
function recalc(p){
  let atk=p.baseAtk*(1+p.skills.power*.1),hp=p.baseHp,mp=p.baseMp,def=p.baseDef,sp=p.baseSpeed,e=p.equip;
  if(e.weapon)atk+=e.weapon.power;
  if(e.head){def+=Math.round(e.head.power*.25);hp+=e.head.power*2}
  if(e.armor){def+=Math.round(e.armor.power*.4);hp+=e.armor.power*4}
  if(e.charm){hp+=e.charm.power*2;mp+=Math.round(e.charm.power*.6)}
  if(e.boots)sp+=e.boots.power*2;
  if(e.artifact){atk+=Math.round(e.artifact.power*.5);mp+=Math.round(e.artifact.power*1.2)}
  if(p.buffs&&p.buffs.inn>0){atk+=2;def+=1;hp+=10;mp+=6}
  const oldHpMax=p.maxHp||hp, oldMpMax=p.maxMp||mp;
  p.attack=Math.round(atk);p.maxHp=Math.round(hp);p.maxMp=Math.round(mp);p.def=def;p.speed=sp;
  if(!p.hp)p.hp=p.maxHp; else p.hp=Math.min(p.maxHp,p.hp+p.maxHp-oldHpMax);
  if(!p.mp&&p.mp!==0)p.mp=p.maxMp; else if(oldMpMax===0)p.mp=p.maxMp; else p.mp=Math.min(p.maxMp,p.mp+p.maxMp-oldMpMax);
}
function makeEnemy(type,x,y,level=1,sc='world'){
  const cfg={warrior:[88,88,12,16,270,'cat_warrior'],archer:[70,79,14,16,320,'cat_archer'],mage:[68,74,16,16,335,'cat_mage'],elite:[200,102,20,19,360,'cat_elite'],king:[430,112,26,24,410,'cat_king']}[type],m=1+(level-1)*.13;
  return {kind:'enemy',type,x,y,homeX:x,homeY:y,scene:sc,level,sheet:cfg[5],hp:Math.round(cfg[0]*m),maxHp:Math.round(cfg[0]*m),speed:cfg[1],dmg:Math.round(cfg[2]*m),r:cfg[3],aggro:cfg[4],leash:type==='king'?720:590,state:'idle',alert:0,cd:rnd(.9,1.8),wander:0,wx:x,wy:y,flash:0,anim:rnd(0,3),recover:0,phase:1,lastHitBy:0,lastHitAt:-99,lastPackAt:-99};
}
function seedDynamicWorld(){
  enemies=[];chests=[];loot=[];effects=[];hazards=[];respawnQueue=[];gameCompleted=false;victoryShown=false;victoryDelay=0;
  [['warrior',900,1100,1],['archer',1450,650,2],['mage',1100,2900,2],['elite',1600,3650,3],['warrior',3900,850,2],['archer',4300,1550,2],['mage',4700,2300,3],['warrior',5350,1350,3],['elite',5500,3500,4],['archer',3900,3300,3],['warrior',3500,3000,2],['mage',5700,2150,4]].forEach(a=>{
    const p=projectEnemySpawnOutsideTown(a[1],a[2]);
    enemies.push(makeEnemy(a[0],p.x,p.y,a[3],'world'));
  });
  [['warrior',360,350,3,'dungeon'],['archer',640,280,3,'dungeon'],['mage',950,430,4,'dungeon'],['elite',1200,640,4,'dungeon'],['king',1450,760,5,'dungeon']].forEach(a=>enemies.push(makeEnemy(...a)));
  chests=[{scene:'world',x:900,y:900,tier:0,asset:'chest_common',open:false,openAnim:0,opening:false},{scene:'world',x:4300,y:1100,tier:1,asset:'chest_rare',open:false,openAnim:0,opening:false},{scene:'world',x:5100,y:3200,tier:2,asset:'chest_epic',open:false,openAnim:0,opening:false},{scene:'dungeon',x:1510,y:900,tier:3,asset:'chest_legendary',open:false,openAnim:0,opening:false,final:true}];
  interiorNpcs=[
    {scene:'house',x:500,y:340,name:'Toto',asset:'npc_toto',lines:['Mi casa es chica, pero por lo menos no tiene gatos adentro.']},
    {scene:'forge',x:500,y:340,name:'Rufus',asset:'npc_rufus',lines:['Tengo equipo básico para vender.','Si me traés dos metales gatunos te refuerzo el arma.'],action:()=>{acceptQuest('metal');openShop();}},
    {scene:'inn',x:500,y:340,name:'Barto',asset:'npc_barto',lines:['Una cama, un hueso y una siesta.','Al terminar este diálogo te cobro 15 monedas y te curo.'],action:restAtInn},
    {scene:'elder',x:500,y:340,name:'Mora',asset:'npc_mora',lines:['Un artefacto importante puede cambiar toda una build.']}
  ];
  initWorldNpcStates();
}

