function showQuestToast(text){if(!UI.questToast)return;UI.questToast.textContent=text;UI.questToast.style.display='flex';questToastTimer=2.5;}
function acceptQuest(id){const q=quests[id];if(!q.active&&!q.claimed){q.active=true;selectedQuestId=id;setMessage('Nueva misión: '+q.title);showQuestToast(q.title);}renderQuestLog();}
function checkQuests(){
  if(quests.cats.active&&!quests.cats.done&&kills>=quests.cats.target){quests.cats.done=true;setMessage('✅ Misión lista: '+quests.cats.title);}
  if(quests.metal.active&&!quests.metal.done){quests.metal.count=Math.min(quests.metal.target,materials.metal);if(quests.metal.count>=quests.metal.target){quests.metal.done=true;setMessage('✅ Rufus ya puede reforzar tu arma.');}}
  const kingAlive=enemies.some(e=>e.type==='king'&&e.hp>0); if(quests.cave.active&&!quests.cave.done&&!kingAlive){quests.cave.done=true;setMessage('✅ El Rey Gato cayó. El cofre legendario quedó desbloqueado.');}
  renderQuestLog();
}
function claimQuest(id){const q=quests[id],p=players[0];if(!q.done||q.claimed)return;AudioManager.play('quest');if(id==='cats'){gold+=80;consumables.potion+=1;pickupItem(p,makeItem('armor',p.level+1,1));}else if(id==='metal'){materials.metal=Math.max(0,materials.metal-2);if(p.equip.weapon)p.equip.weapon.power+=6;else pickupItem(p,makeItem('weapon',p.level+1,1));recalc(p);}else if(id==='cave'){consumables.potion+=2;pickupItem(p,makeItem('artifact',p.level+2,2));recalc(p);}q.claimed=true;setMessage('Recompensa obtenida: '+q.reward);renderQuestLog();renderHud();}
function gainXP(p,a){p.xp+=a;while(p.xp>=p.next){p.xp-=p.next;p.level++;p.points++;p.next=Math.round(p.next*1.28);p.baseHp+=12;p.baseAtk+=3;recalc(p);p.hp=p.maxHp;effects.push({kind:'level',x:p.x,y:p.y,life:.9,max:.9});AudioManager.play('level');}}
function pickupItem(p,it){
  p.inventory.unshift(it);p.inventory=p.inventory.slice(0,18);
  let autoEquipped=false;
  if(it&&it.slot&&p.equip&&p.equip[it.slot]==null){p.equip[it.slot]=it;recalc(p);autoEquipped=true;}
  AudioManager.play('pickup');showToast(it,autoEquipped);
  if(autoEquipped)setMessage(`Equipado automáticamente: ${it.name}`);
  renderInventory();
}
function showToast(it,autoEquipped=false){UI.toast.style.display='block';UI.toast.style.borderColor=it.color;UI.toastImg.src=ASSET_PATHS[it.asset];UI.toastTier.textContent=it.rarity;UI.toastTier.style.color=it.color;UI.toastName.textContent=it.name;UI.toastInfo.textContent=`${SLOT_LABEL[it.slot]} · Poder +${it.power}${autoEquipped?' · Autoequipado':''}`;toastTimer=2.4;}
function openChest(ch,p){
  if(ch.open)return;
  if(ch.final&&enemies.some(e=>e.scene==='dungeon'&&e.type==='king'&&e.hp>0)){
    setMessage('🔒 El sello del Rey Gato mantiene este cofre cerrado.');AudioManager.play('uiClose');return;
  }
  ch.open=true;ch.opening=true;ch.openAnim=0;AudioManager.play('chest');
  effects.push({kind:'level',x:ch.x,y:ch.y-10,life:.48,max:.48});
  if(ch.final){pickupItem(p,makeItem('artifact',p.level+2,3));gold+=90;setMessage('💎 ¡Cofre legendario abierto!');}
  else{const arr=['head','weapon','armor','charm','boots','artifact'];pickupItem(p,makeItem(arr[Math.floor(rnd(0,arr.length))],p.level+1,ch.tier));}
}

function worldNpcData(obj){
  const role=NPC_ROLE_META[obj.name]||NPC_ROLE_META.default;
  let lines=['Buen día, cachorro.'];
  let action=null;
  if(obj.name==='Toto'){
    lines=quests.cats.claimed?[
      'Buen trabajo con la caza. El camino quedó mucho más tranquilo.',
      'Si ves otra manada rara, avisame. Yo ya estoy cebado.'
    ]:[
      'Los gatos volvieron a los caminos.',
      quests.cats.active&&!quests.cats.done?`Llevás ${kills}/${quests.cats.target}. Seguí así.`:'Si seguís despejando la zona, el pueblo respira tranquilo.',
      'Derrotá seis y te pago por el trabajo. Ya te marqué una zona de caza en el minimapa.'
    ];
    action=()=>acceptQuest('cats');
  }
  if(obj.name==='Rufus'){
    lines=[
      'La herrería está abierta.',
      quests.metal.done&&!quests.metal.claimed?'Tengo lista tu mejora. Cobrá la misión y después mirá mi stock.':gold>=30?'Con esas monedas ya te alcanza para un equipo decente.':'Si juntás unas monedas, te armo algo mejor.',
      'Si querés, al terminar el diálogo te abro la tienda.'
    ];
    action=()=>{acceptQuest('metal');openShop();};
  }
  if(obj.name==='Barto'){
    lines=[
      'La Posada del Hueso sigue abierta.',
      'Por 15 monedas te curo y te doy un guiso que mejora ataque y defensa por un rato.',
      gold>=15?'Cuando cierres el diálogo te dejo pipón y listo para seguir peleando.':'Volvé con algunas monedas y te dejo nuevo.'
    ];
    action=openInnShop;
  }
  if(obj.name==='Mora'){
    if(!quests.cats.done&&!quests.cats.claimed){
      lines=[
        'Antes de ir a la cueva, ayudá a Toto a limpiar los caminos.',
        'Una manada que no protege su entrada no merece su tesoro.',
        'Cuando termines, vuelvo a hablarte del Rey Gato.'
      ];
      action=()=>openQuestLog();
    }else{
      lines=[
        'Hay una cueva al sudeste, lejos del pueblo.',
        'La marqué en tu minimapa con un icono dorado.',
        quests.cave.done?'Volviste del maullido… sabía que podían hacerlo.':'Entrá y derrotá al Rey Gato que te está esperando.'
      ];
      action=()=>{acceptQuest('cave');openQuestLog();};
    }
  }
  return {scene:'world',x:obj.x,y:obj.y,name:obj.name,role:role.title,roleColor:role.color,asset:obj.props.asset,lines,action};
}
function npcPositionBlocked(x,y,r=11){
  for(const rect of mapCollisions){if(circleRectHit(x,y,r,rect))return true;}
  return false;
}
function chooseNpcDestination(n){
  const b=n.behavior||NPC_BEHAVIOR.default;
  for(let i=0;i<14;i++){
    const usePlaza=villagePlaza&&Math.random()<b.plazaBias;
    const anchorX=usePlaza?villagePlaza.x:n.originX,anchorY=usePlaza?villagePlaza.y:n.originY;
    const radius=usePlaza?Math.min(villagePlaza.rx*.62,b.radius+12):b.radius;
    const a=rnd(0,Math.PI*2),rr=rnd(14,radius);
    const tx=anchorX+Math.cos(a)*rr,ty=anchorY+Math.sin(a)*rr*.78;
    if(villageGroundBounds&&(tx<villageGroundBounds.minX||tx>villageGroundBounds.maxX||ty<villageGroundBounds.minY||ty>villageGroundBounds.maxY))continue;
    if(villageCenterpiece&&Math.hypot(tx-villageCenterpiece.x,ty-villageCenterpiece.y)<92)continue;
    if(npcPositionBlocked(tx,ty,12))continue;
    n.targetX=tx;n.targetY=ty;n.moving=true;n.idleMode='walk';return true;
  }
  n.targetX=n.originX;n.targetY=n.originY;n.moving=true;n.idleMode='walk';return false;
}
function setNpcIdle(n,forced=null){
  const modes=['stand','blink','look','sniff'];
  n.idleMode=forced||modes[Math.floor(rnd(0,modes.length))];
  n.poseTimer=rnd(.45,1.4);
}
function pickWorldNpcTarget(n){ chooseNpcDestination(n); }
function moveWorldNpc(n,dx,dy){
  const oldX=n.x,oldY=n.y;
  n.x+=dx;if(npcPositionBlocked(n.x,n.y,10))n.x=oldX;
  n.y+=dy;if(npcPositionBlocked(n.x,n.y,10))n.y=oldY;
}
function updateWorldNpcs(dt){
  if(scene!=='world'||!npcWorldStates.length)return;
  for(const n of npcWorldStates){
    const b=n.behavior||NPC_BEHAVIOR.default;
    n.anim+=dt;n.bob+=dt*(n.moving?4.8:1.2);
    if(n.wait>0){
      n.wait-=dt;n.speedNow=0;n.moving=false;n.poseTimer-=dt;
      if(n.poseTimer<=0){
        if(Math.random()<b.turnChance){
          const dirs=[[0,1],[0,-1],[-1,0],[1,0]],pick=dirs[Math.floor(Math.random()*dirs.length)];
          n.dirX=pick[0];n.dirY=pick[1];
        }
        setNpcIdle(n,Math.random()<b.inspectChance?'look':null);
      }
      if(n.wait<=0)pickWorldNpcTarget(n);
      continue;
    }
    const dx=n.targetX-n.x,dy=n.targetY-n.y,d=Math.hypot(dx,dy)||1;
    if(d<3){
      n.x=n.targetX;n.y=n.targetY;n.speedNow=0;n.moving=false;
      n.wait=rnd(b.pause[0],b.pause[1]);
      setNpcIdle(n,Math.random()<b.inspectChance?'look':null);
      continue;
    }
    const vx=dx/d,vy=dy/d,step=Math.min(d,n.speed*dt);
    n.dirX=vx;n.dirY=vy;
    moveWorldNpc(n,vx*step,vy*step);
    if(Math.abs(n.x-(n.targetX-dx))<.001&&Math.abs(n.y-(n.targetY-dy))<.001){n.wait=.35;setNpcIdle(n,'look');}
    n.speedNow=step/dt;n.moving=true;n.idleMode='walk';
  }
}
function activeNpcs(){
  if(scene==='world'){
    if(!npcWorldStates.length)initWorldNpcStates();
    return npcWorldStates.map(st=>{const base=worldNpcData(st.obj);return {...base,x:st.x,y:st.y,dirX:st.dirX,dirY:st.dirY,anim:st.anim,moving:st.moving,sheet:st.obj.props.asset+'_sheet',idleMode:st.idleMode,bob:st.bob};});
  }
  return interiorNpcs.filter(n=>n.scene===scene);
}
function updateDialogVisualState(){if(!dialogState){UI.dialog.classList.remove('typing');UI.dialogText.classList.remove('typing');return;}const typing=!!dialogState.typing;UI.dialog.classList.toggle('typing',typing);UI.dialogText.classList.toggle('typing',typing);}
function updateDialogActionLabel(){if(!UI.dialogAction||!dialogState)return;if(dialogState.typing){UI.dialogAction.textContent='Completar';return;}UI.dialogAction.textContent=dialogState.index>=dialogState.npc.lines.length-1?'Cerrar':'Continuar';}
function setDialogueLine(text){if(!dialogState)return;dialogState.fullText=String(text||'');dialogState.visibleText='';dialogState.charIndex=0;dialogState.charClock=0;dialogState.charDelay=.018;dialogState.voiceClock=0;dialogState.typing=true;UI.dialogText.textContent='';updateDialogVisualState();updateDialogActionLabel();}
function finishDialogueTyping(){if(!dialogState)return;dialogState.typing=false;dialogState.charIndex=dialogState.fullText.length;dialogState.visibleText=dialogState.fullText;UI.dialogText.textContent=dialogState.visibleText;updateDialogVisualState();updateDialogActionLabel();}
function updateDialogueTyping(dt){if(!dialogState||!dialogState.typing)return;dialogState.charClock+=dt;dialogState.voiceClock=(dialogState.voiceClock||0)+dt;while(dialogState.charClock>=dialogState.charDelay&&dialogState.charIndex<dialogState.fullText.length){dialogState.charClock-=dialogState.charDelay;dialogState.charIndex++;dialogState.visibleText=dialogState.fullText.slice(0,dialogState.charIndex);UI.dialogText.textContent=dialogState.visibleText;const ch=dialogState.fullText[dialogState.charIndex-1];if(/[^\s]/.test(ch)&&dialogState.voiceClock>.065){AudioManager.play('dialog');dialogState.voiceClock=0;}if(/[.!?…]/.test(ch))dialogState.charClock-=.032;else if(/[,;:]/.test(ch))dialogState.charClock-=.018;}if(dialogState.charIndex>=dialogState.fullText.length)finishDialogueTyping();}
function openDialogue(n){resetTouchMove();dialogState={npc:n,index:0,typing:false,fullText:'',visibleText:'',charIndex:0,charClock:0,charDelay:.018,voiceClock:0};overlay='dialog';document.body.classList.add('dialog-open');document.body.classList.remove('overlay-open');UI.dialog.style.display='block';UI.dialogPortrait.src=ASSET_PATHS[n.asset];UI.dialogName.textContent=n.name;if(UI.dialogRole)UI.dialogRole.textContent=n.role?`${n.role} · Aldea Canina`:'Habitante · Aldea Canina';setDialogueLine(n.lines[0]);AudioManager.play('uiOpen');}
function advanceDialogue(){if(!dialogState){closeOverlay();return;}if(dialogState.typing){finishDialogueTyping();AudioManager.play('dialog');return;}dialogState.index++;if(dialogState.index>=dialogState.npc.lines.length){const a=dialogState.npc.action;AudioManager.play('uiClose');closeOverlay();if(a)a();return;}setDialogueLine(dialogState.npc.lines[dialogState.index]);AudioManager.play('dialog');}
function applyInnBuff(){players.forEach(p=>{if(!p.buffs)p.buffs={inn:0};p.buffs.inn=TOWN_RPG_DATA.stew.duration;recalc(p);p.hp=p.maxHp;effects.push({kind:'heal',x:p.x,y:p.y,life:.9,max:.9});});}
function restAtInn(){if(gold<15){setMessage('No tenés suficientes monedas para la posada.');return;}gold-=15;AudioManager.play('heal');applyInnBuff();setMessage('🛏️ Descansaste. Vida al máximo y guiso de Barto activo por 3 minutos.');}
function usePotion(p=players[0]){if(!p||p.hp<=0)return;if(consumables.potion<=0){setMessage('No te quedan pociones. Barto vende más en la posada.');return;}if(p.hp>=p.maxHp&&p.mp>=p.maxMp){setMessage('Tus recursos ya están al máximo.');return;}consumables.potion--;const healed=Math.max(1,Math.round(p.maxHp*TOWN_RPG_DATA.potion.healRatio)),restored=Math.max(8,Math.round(p.maxMp*.22));p.hp=Math.min(p.maxHp,p.hp+healed);p.mp=Math.min(p.maxMp,p.mp+restored);AudioManager.play('heal');effects.push({kind:'heal',x:p.x,y:p.y,life:.75,max:.75});effects.push({kind:'uiBadge',asset:'ui_heal_badge',x:p.x,y:p.y-34,life:.85,max:.85});addDamageNumber(p.x-12,p.y-18,healed,'#58e54f',false);addDamageNumber(p.x+18,p.y-34,restored,'#4aa8ff',false);setMessage(`Poción usada: +${healed} HP y +${restored} MP. Quedan ${consumables.potion}.`);}
function craftAtRufus(kind){const p=players[0],recipe=TOWN_RPG_DATA[kind];if(!p||!recipe)return;const slot=kind==='craftWeapon'?'weapon':'armor',equipped=p.equip[slot];if(!equipped){setMessage(`Equipá ${slot==='weapon'?'un arma':'una pechera'} antes de reforjar.`);return;}if(materials.metal<recipe.metal){setMessage(`Faltan metales gatunos: ${materials.metal}/${recipe.metal}.`);return;}if(gold<recipe.gold){setMessage('No tenés suficientes monedas para la forja.');return;}materials.metal-=recipe.metal;gold-=recipe.gold;equipped.power+=recipe.power;recalc(p);AudioManager.play('quest');effects.push({kind:'level',x:p.x,y:p.y,life:.7,max:.7});setMessage(`⚒️ ${equipped.name} reforzado: +${recipe.power} poder.`);openShop();}
function setShopHeader(title,subtitle){const t=document.getElementById('shopTitle'),s=document.getElementById('shopSubtitle');if(t)t.textContent=title;if(s)s.textContent=subtitle;}
function openShop(){AudioManager.play('uiOpen');overlay='shop';document.body.classList.add('overlay-open');document.body.classList.remove('dialog-open');UI.shop.style.display='flex';setShopHeader('⚒️ Herrería de Rufus',`Metal gatuno: ${materials.metal} · Compra o reforjá equipo.`);const items=[Object.assign(makeItem('weapon',3,1),{name:'Colmillo Azul',power:14}),Object.assign(makeItem('armor',3,1),{name:'Pechera del Pastor',power:12}),Object.assign(makeItem('boots',3,1),{name:'Botas del Galgo',power:11}),Object.assign(makeItem('charm',4,2),{name:'Collar Rúnico',power:16})],prices=[52,58,49,92];const grid=document.getElementById('shopGrid');const itemHtml=items.map((it,i)=>`<button class="shopCard" data-buy="${i}"><img src="${ASSET_PATHS[it.asset]}"><div class="tier" style="color:${it.color}">${it.rarity}</div><b>${it.name}</b><p>${SLOT_LABEL[it.slot]} · Poder +${it.power}<br>🪙 ${prices[i]}</p></button>`).join('');const craftHtml=['craftWeapon','craftArmor'].map(key=>{const r=TOWN_RPG_DATA[key];return `<button class="shopCard" data-craft="${key}"><div style="font-size:2rem">${r.icon}</div><b>${r.name}</b><p>+${r.power} poder al equipo puesto<br>🔩 ${r.metal} · 🪙 ${r.gold}</p></button>`}).join('');grid.innerHTML=itemHtml+craftHtml;grid.querySelectorAll('[data-buy]').forEach((b,i)=>b.onclick=()=>{if(gold<prices[i]){setMessage('No tenés suficientes monedas.');return;}gold-=prices[i];pickupItem(players[0],{...items[i],id:Math.random().toString(36).slice(2)});setMessage('Compraste '+items[i].name+' en la herrería.');});grid.querySelectorAll('[data-craft]').forEach(b=>b.onclick=()=>craftAtRufus(b.dataset.craft));}
function openInnShop(){AudioManager.play('uiOpen');overlay='shop';document.body.classList.add('overlay-open');document.body.classList.remove('dialog-open');UI.shop.style.display='flex';setShopHeader('🛏️ Posada del Hueso',`Pociones: ${consumables.potion} · Hierbas: ${materials.herb}`);const grid=document.getElementById('shopGrid');grid.innerHTML=`<button class="shopCard" data-service="rest"><div style="font-size:2rem">🛏️</div><b>Descansar</b><p>Vida completa + guiso 3 min<br>🪙 15</p></button><button class="shopCard" data-service="potion"><div style="font-size:2rem">🧪</div><b>${TOWN_RPG_DATA.potion.name}</b><p>Cura ${Math.round(TOWN_RPG_DATA.potion.healRatio*100)}% de vida<br>🪙 ${TOWN_RPG_DATA.potion.price}</p></button><button class="shopCard" data-service="brew"><div style="font-size:2rem">🌿</div><b>Preparar poción</b><p>1 hierba → 1 poción<br>🪙 5</p></button>`;grid.querySelector('[data-service=rest]').onclick=()=>{restAtInn();openInnShop();};grid.querySelector('[data-service=potion]').onclick=()=>{if(gold<TOWN_RPG_DATA.potion.price){setMessage('No tenés suficientes monedas.');return;}gold-=TOWN_RPG_DATA.potion.price;consumables.potion++;setMessage('🧪 Compraste una Poción de Hueso.');openInnShop();};grid.querySelector('[data-service=brew]').onclick=()=>{if(materials.herb<1){setMessage('Necesitás una hierba silvestre.');return;}if(gold<5){setMessage('Necesitás 5 monedas para prepararla.');return;}materials.herb--;gold-=5;consumables.potion++;setMessage('🌿 Barto preparó una poción con tu hierba.');openInnShop();};}
function interact(){
  if(onlineCoop.active){setMessage('ONLINE Phase 6: NPCs, cofres y cueva todavía no se sincronizan.');return;}
  if(overlay==='dialog'){advanceDialogue();return;}if(overlay)return;const p=players[0];
  const n=activeNpcs().map(n=>({n,d:dist(p,n)})).filter(v=>v.d<112).sort((a,b)=>a.d-b.d)[0];
  if(n){if(n.n.name==='Toto'&&quests.cats.done&&!quests.cats.claimed){claimQuest('cats');return;}if(n.n.name==='Rufus'&&quests.metal.done&&!quests.metal.claimed){claimQuest('metal');return;}if(n.n.name==='Mora'&&quests.cave.done&&!quests.cave.claimed){claimQuest('cave');return;}openDialogue(n.n);return;}
  const ch=chests.find(c=>c.scene===scene&&!c.open&&dist(p,c)<82);if(ch){openChest(ch,p);return;}
  if(scene==='world'){
    const building=mapObjects.filter(o=>o.type==='building').map(o=>({o,d:Math.hypot(p.x-o.x,p.y-o.y)})).filter(v=>v.d<125).sort((a,b)=>a.d-b.d)[0];
    if(building){scene=building.o.props.objectId;inside=building.o.props.objectId;players.forEach((pl,i)=>{pl.x=470+i*60;pl.y=545});camera.x=500;camera.y=350;setMessage('Entraste a '+building.o.name);return;}
    const cave=mapObjects.find(o=>o.type==='cave');if(cave&&(nearWorldTrigger(p,caveTrigger,18)||Math.hypot(p.x-cave.x,p.y-(cave.y+76))<165)){scene='dungeon';inside='dungeon';players.forEach((pl,i)=>{pl.x=190+i*60;pl.y=930});camera.x=430;camera.y=780;setMessage('Entraste a la Cueva del Maullido. Seguí el camino iluminado hasta el Rey Gato.');return;}
  } else if(scene==='dungeon'){
    if(p.x<285&&p.y>865){scene='world';inside=null;const cave=mapObjects.find(o=>o.type==='cave');players.forEach((pl,i)=>{pl.x=cave.x-185+i*60;pl.y=cave.y+165});camera.x=cave.x-120;camera.y=cave.y+120;setMessage('Volviste al valle.');return;}
  } else if(p.y>565){
    const b=mapObjects.find(o=>o.props.objectId===inside);scene='world';inside=null;players.forEach((pl,i)=>{pl.x=b.x+i*60;pl.y=b.y+115});camera.x=b.x;camera.y=b.y+120;setMessage('Volviste al pueblo.');
  }
}

// ---------------------------
// Collision
// ---------------------------
function circleRectHit(x,y,r,rect){const cx=clamp(x,rect.x,rect.x+rect.width),cy=clamp(y,rect.y,rect.y+rect.height);return (x-cx)*(x-cx)+(y-cy)*(y-cy)<r*r;}
function nearWorldTrigger(p,tr,pad=0){if(!tr)return false;const hw=(tr.width||0)/2,hh=(tr.height||0)/2;return p.x>=tr.x-hw-pad&&p.x<=tr.x+hw+pad&&p.y>=tr.y-hh-pad&&p.y<=tr.y+hh+pad;}
function worldCollisionRectsNear(p){const pad=80;return mapCollisions.filter(r=>r.x+r.width>=p.x-pad&&r.x<=p.x+pad&&r.y+r.height>=p.y-pad&&r.y<=p.y+pad);}
function movePlayer(p,dx,dy){
  if(scene!=='world'){p.x+=dx;p.y+=dy;return;}
  const rects=worldCollisionRectsNear(p);const oldX=p.x,oldY=p.y;
  p.x+=dx;for(const r of rects){if(circleRectHit(p.x,p.y,p.r,r)){p.x=oldX;break;}}
  p.y+=dy;for(const r of rects){if(circleRectHit(p.x,p.y,p.r,r)){p.y=oldY;break;}}
}

// ---------------------------
// Combat / AI
// ---------------------------
function attack(p){
  if(onlineCoop.active){onlineAttack(p);return;}
  if(p.attackCd>0||p.hp<=0)return;
  AudioManager.play('attack');
  p.combo=p.comboTimer>0?(p.combo%3)+1:1;p.comboTimer=.72;
  const spec=p.combo===1?{reach:90,mult:1,cd:.23,knock:14}:p.combo===2?{reach:104,mult:1.28,cd:.28,knock:22}:{reach:128,mult:1.82,cd:.44,knock:44};
  p.attackCd=spec.cd;p.state='attack';
  const ang=Math.atan2(p.dirY,p.dirX);
  effects.push({kind:'slash',x:p.x+p.dirX*22,y:p.y+p.dirY*15,angle:ang,life:(p.combo===3 ? .28 : .20),max:(p.combo===3 ? .28 : .20),strong:p.combo===3,combo:p.combo});
  addSlashTrail(p.x+p.dirX*26,p.y+p.dirY*15,ang,p.combo===3,p.combo);
  if(p.combo===3)addDamageNumber(p.x+p.dirX*12,p.y-16,'FINISHER','#f4d79a',true);
  enemies.filter(e=>e.scene===scene&&e.hp>0).forEach(e=>{const dx=e.x-p.x,dy=e.y-p.y,d=Math.hypot(dx,dy)||1,dot=dx/d*p.dirX+dy/d*p.dirY;if(d<spec.reach+e.r&&dot>-.12){const crit=Math.random()<.12;const amount=p.attack*spec.mult*(crit?1.6:1);damageEnemy(p,e,amount,{crit,strong:p.combo===3,knock:spec.knock,color:'#fff'});effects.push({kind:'impact',x:e.x,y:e.y,life:(p.combo===3 ? .3 : .22),max:(p.combo===3 ? .3 : .22),large:p.combo===3});}});
}
function dash(p){
  const cost=28-p.skills.dash*4;if(p.dashCd>0||p.stam<cost||p.hp<=0)return;
  AudioManager.play('dash');p.stam-=cost;p.dashCd=.38;p.inv=.34;p.state='dash';
  effects.push({kind:'dash',x:p.x,y:p.y,life:.26,max:.26});
  const len=(p.role==='Rastreadora'?160:132)+p.skills.dash*22;movePlayer(p,p.dirX*len,p.dirY*len);
  effects.push({kind:'dash',x:p.x-p.dirX*22,y:p.y-p.dirY*12,life:.18,max:.18});
}
function useSkill(p){
  if(onlineCoop.active){onlineSkill(p);return;}
  const cost=Math.max(18,28-p.skills.howl*4);
  if(p.skillCd>0||p.hp<=0||p.mp<cost)return;
  AudioManager.play('skill');p.mp-=cost;p.skillCd=5.1;p.state='skill';
  const r=205+p.skills.howl*40,dmg=Math.round(p.attack*(1.35+p.skills.howl*.28));effects.push({kind:'howl',x:p.x,y:p.y,life:.75,max:.75});triggerShake(3.2);gameVibrate(22);
  enemies.filter(e=>e.scene===scene&&e.hp>0).forEach(e=>{if(dist(p,e)<r)damageEnemy(p,e,dmg,{strong:true,knock:34,color:'#d7c2ff'});});
}
function nearestTarget(e){const living=players.filter(p=>p.hp>0);return living.length?living.slice().sort((a,b)=>dist(a,e)-dist(b,e))[0]:null;}
function engagedNearby(e){return enemies.filter(o=>o.scene===scene&&o!==e&&o.state==='aggro'&&dist(o,e)<430).length;}
function hurtPlayer(p,dmg){
  if(p.inv>0||p.hp<=0)return false;const dealt=Math.max(1,Math.round(dmg-p.def));p.hp-=dealt;p.inv=.56;p.flash=.18;if(p.hp<0)p.hp=0;
  addDamageNumber(p.x,p.y,dealt,'#ff8b83',false);addImpactParticles(p.x,p.y,'#ff8b83',6,true);addImpactBurst(p.x,p.y,'rgba(255,122,122,.88)',true,false);triggerShake(4);triggerHitStop(.032);gameVibrate([22,14,18]);return true;
}
function updatePlayer(p,dt){
  if(p.hp<=0){p.state='dead';return;}let mx=0,my=0;
  const primaryControls=onlineCoop.active?true:p.id===1;
  if(primaryControls){mx=(keys.KeyD?1:0)-(keys.KeyA?1:0);my=(keys.KeyS?1:0)-(keys.KeyW?1:0);if(touchMode){mx+=touchMove.x;my+=touchMove.y;}if(keys.KeyF){attack(p);keys.KeyF=false}if(keys.KeyG){dash(p);keys.KeyG=false}if(keys.KeyH){useSkill(p);keys.KeyH=false}}
  else{mx=(keys.ArrowRight?1:0)-(keys.ArrowLeft?1:0);my=(keys.ArrowDown?1:0)-(keys.ArrowUp?1:0);if(keys.KeyL){attack(p);keys.KeyL=false}if(keys.KeyK){dash(p);keys.KeyK=false}if(keys.KeyJ){useSkill(p);keys.KeyJ=false}}
  if(mx||my){const l=Math.hypot(mx,my);mx/=l;my/=l;p.dirX=mx;p.dirY=my;movePlayer(p,mx*p.speed*dt,my*p.speed*dt);p.anim+=dt;if(p.attackCd<=0&&p.dashCd<=0&&p.skillCd<4.6)p.state='run';}else{p.anim+=dt*.6;if(p.attackCd<=0&&p.dashCd<=0&&p.skillCd<4.6)p.state='idle';}
  p.attackCd=Math.max(0,p.attackCd-dt);p.dashCd=Math.max(0,p.dashCd-dt);p.skillCd=Math.max(0,p.skillCd-dt);p.comboTimer=Math.max(0,p.comboTimer-dt);p.inv=Math.max(0,p.inv-dt);p.flash=Math.max(0,p.flash-dt);p.stam=clamp(p.stam+36*dt,0,100);p.mp=clamp(p.mp+10*dt,0,p.maxMp);if(p.buffs&&p.buffs.inn>0){const prev=p.buffs.inn;p.buffs.inn=Math.max(0,p.buffs.inn-dt);if(prev>0&&p.buffs.inn===0){recalc(p);if(p.id===1)setMessage('El efecto del guiso de Barto se terminó.');}}
  if(scene==='world'){p.x=clamp(p.x,p.r,mapWidthPx-p.r);p.y=clamp(p.y,p.r,mapHeightPx-p.r)}else if(scene==='dungeon'){p.x=clamp(p.x,80,1720);p.y=clamp(p.y,80,1120)}else{p.x=clamp(p.x,85,920);p.y=clamp(p.y,90,620)}
  for(let i=loot.length-1;i>=0;i--)if(loot[i].scene===scene&&dist(p,loot[i])<52){pickupItem(p,loot[i].item);loot.splice(i,1)}
}
function updateEnemy(e,dt){
  if(e.scene!==scene)return;e.flash=Math.max(0,e.flash-dt);e.alert=Math.max(0,e.alert-dt);e.cd-=dt;e.anim+=dt;e.recover=Math.max(0,(e.recover||0)-dt);if(e.hp<=0)return;
  if(e.type==='king'&&e.phase===1&&e.hp<=e.maxHp*.5){e.phase=2;e.speed=Math.round(e.speed*1.12);e.dmg+=5;e.leash=820;setMessage('🔥 El Rey Gato entra en Fase 2: ataques más rápidos.');effects.push({kind:'howl',x:e.x,y:e.y,life:.85,max:.85});triggerShake(6);gameVibrate([35,25,45]);}
  const p=nearestTarget(e);if(!p)return;const pd=dist(e,p),hd=Math.hypot(e.x-e.homeX,e.y-e.homeY);
  if(e.scene==='world'){
    if(isInsideTownSafeZone(e.x,e.y,0)){e.state='return';}
    if(isInsideTownSafeZone(p.x,p.y,0)&&(e.state==='aggro'||e.state==='alert'))e.state='return';
  }
  if(e.recover>0)return;
  if(e.state==='idle'){if(pd<e.aggro&&engagedNearby(e)<2){e.state='alert';e.alert=.55;return}e.wander-=dt;if(e.wander<=0){e.wander=rnd(2.4,4.6);const a=rnd(0,6.28),rr=rnd(20,100);e.wx=e.homeX+Math.cos(a)*rr;e.wy=e.homeY+Math.sin(a)*rr;if(e.scene==='world'&&isInsideTownSafeZone(e.wx,e.wy,0)){e.wx=e.homeX;e.wy=e.homeY}}const dx=e.wx-e.x,dy=e.wy-e.y,d=Math.hypot(dx,dy)||1;if(d>8){const nx=e.x+dx/d*e.speed*.18*dt,ny=e.y+dy/d*e.speed*.18*dt;if(e.scene!=='world'||!isInsideTownSafeZone(nx,ny,0)){e.x=nx;e.y=ny}}return}
  if(e.state==='alert'){if(pd>e.aggro+90)e.state='idle';else if(e.alert<=0)e.state='aggro';return}
  if(e.state==='aggro'){
    if(pd>e.leash||hd>e.leash){e.state='return';return}
    const dx=p.x-e.x,dy=p.y-e.y,d=Math.hypot(dx,dy)||1;
    if(e.cd<=0){
      if(e.type==='archer'){
        const vx=dx/d*330,vy=dy/d*330;hazards.push({scene:e.scene,x:e.x,y:e.y,r:18,life:2.15,max:2.15,dmg:e.dmg,type:'archer',kind:'projectile',vx,vy,age:0});e.cd=2.05;
      }else if(e.type==='mage'){
        const leadX=p.x+(p.dirX||0)*42,leadY=p.y+(p.dirY||0)*42;hazards.push({scene:e.scene,x:leadX,y:leadY,r:92,life:.92,max:.92,dmg:e.dmg,type:'mage',kind:'zone'});e.cd=2.3;
      }else if(e.type==='elite'){
        hazards.push({scene:e.scene,x:p.x,y:p.y,r:84,life:.9,max:.9,dmg:e.dmg,type:'elite',kind:'heavy'});e.cd=1.55;e.recover=.48;
      }else if(e.type==='king'){
        const phase=e.phase||1;hazards.push({scene:e.scene,x:p.x,y:p.y,r:phase===2?104:94,life:phase===2?.68:.82,max:phase===2?.68:.82,dmg:e.dmg,type:'king',kind:'heavy'});
        if(phase===2){const ang=Math.atan2(dy,dx);for(const off of [-.7,.7])hazards.push({scene:e.scene,x:p.x+Math.cos(ang+off)*74,y:p.y+Math.sin(ang+off)*74,r:58,life:.74,max:.74,dmg:Math.round(e.dmg*.72),type:'king',kind:'zone'});}e.cd=phase===2?1.05:1.5;e.recover=phase===2?.28:.38;
      }else{
        hazards.push({scene:e.scene,x:p.x,y:p.y,r:62,life:.56,max:.56,dmg:e.dmg,type:'warrior',kind:'melee'});e.cd=1.75;
      }
    }
    const desired=e.type==='archer'?245:e.type==='mage'?250:e.type==='king'?100:e.type==='elite'?95:82;if(d>desired){const nx=e.x+dx/d*e.speed*dt,ny=e.y+dy/d*e.speed*dt;if(e.scene==='world'&&isInsideTownSafeZone(nx,ny,0)){e.state='return';return;}e.x=nx;e.y=ny}return
  }
  if(e.state==='return'){const dx=e.homeX-e.x,dy=e.homeY-e.y,d=Math.hypot(dx,dy)||1;if(d<15){e.x=e.homeX;e.y=e.homeY;e.state='idle'}else{e.x+=dx/d*e.speed*.62*dt;e.y+=dy/d*e.speed*.62*dt}}
}

function queueEnemyRespawn(e){
  if(e.type==='king')return;
  const extra=e.type==='elite'?10:0;
  respawnQueue.push({type:e.type,x:e.homeX,y:e.homeY,level:e.level,scene:e.scene,timer:(e.scene==='dungeon'?RESPAWN_DUNGEON_TIME:RESPAWN_WORLD_TIME)+extra});
}
function processRespawns(dt){
  for(let i=respawnQueue.length-1;i>=0;i--){
    const r=respawnQueue[i];r.timer-=dt;if(r.timer>0)continue;
    const occupied=enemies.some(e=>e.scene===r.scene&&e.type===r.type&&Math.hypot(e.homeX-r.x,e.homeY-r.y)<24);
    if(occupied){respawnQueue.splice(i,1);continue;}
    const tooClose=scene===r.scene&&players.some(p=>p.hp>0&&Math.hypot(p.x-r.x,p.y-r.y)<RESPAWN_SAFE_RADIUS);
    if(tooClose){r.timer=3;continue;}
    const e=makeEnemy(r.type,r.x,r.y,r.level,r.scene);e.state='idle';enemies.push(e);
    if(scene===r.scene&&isVisibleWorld(r.x,r.y,160)){effects.push({kind:'level',x:r.x,y:r.y,life:.38,max:.38});setMessage('🐈 Un grupo de gatos volvió a patrullar la zona.');}
    respawnQueue.splice(i,1);
  }
}
function showVictoryOverlay(){
  if(victoryShown)return;victoryShown=true;overlay='victory';resetTouchMove();document.body.classList.add('overlay-open');document.body.classList.remove('dialog-open');
  const lead=players[0]||{level:1};document.getElementById('victoryLevel').textContent=lead.level;document.getElementById('victoryKills').textContent=kills;document.getElementById('victoryGold').textContent=gold;
  UI.victory.style.display='flex';AudioManager.play('level');gameVibrate([45,35,80,40,100]);
}
function triggerGameCompletion(){
  if(gameCompleted)return;gameCompleted=true;victoryDelay=1.15;triggerShake(9);setMessage('👑 ¡El Rey Gato fue derrotado!');
}
function processVictory(dt){if(gameCompleted&&!victoryShown&&victoryDelay>0){victoryDelay-=dt;if(victoryDelay<=0)showVictoryOverlay();}}
function continueAfterVictory(){
  UI.victory.style.display='none';overlay=null;document.body.classList.remove('overlay-open');setMessage('🐾 Beta completada. Podés seguir explorando todo lo que quieras.');app.focus();requestAnimationFrame(resizeGame);
}

function cleanupEnemies(){
  for(let i=enemies.length-1;i>=0;i--){
    const e=enemies[i];if(e.hp>0)continue;
    enemies.splice(i,1);
    if(e.type!=='king'){kills++;queueEnemyRespawn(e);}else triggerGameCompletion();
    gold+=e.type==='king'?160:Math.round(rnd(4,11));
    players.forEach(p=>gainXP(p,e.type==='king'?160:e.type==='elite'?52:26));
    if(e.type!=='king'){if(e.type==='elite'||Math.random()<.28){materials.metal++;if(quests.metal.active&&!quests.metal.done)quests.metal.count=Math.min(quests.metal.target,materials.metal);setMessage('🔩 Encontraste metal gatuno.');}else if(Math.random()<.34){materials.herb++;setMessage('🌿 Encontraste una hierba silvestre.');}}
    if(e.type==='king')loot.push({scene:e.scene,x:e.x,y:e.y,item:makeItem('artifact',e.level+1,3),t:0});
    else if(Math.random()<(e.type==='elite'?.9:.42)){const slots=['head','weapon','armor','charm','boots','artifact'];loot.push({scene:e.scene,x:e.x,y:e.y,item:makeItem(slots[Math.floor(rnd(0,slots.length))],e.level,e.type==='elite'?2:null),t:0});}
    effects.push({kind:'impact',x:e.x,y:e.y,life:.4,max:.4,large:true});
  }
  checkQuests();
}
function update(dt){
  if(onlineCoop.active){const lp=onlineLocalPlayer();if(lp)updatePlayer(lp,dt);updateOnlineCoop(dt);updateWorldNpcs(dt);}else{players.forEach(p=>updatePlayer(p,dt));updateWorldNpcs(dt);enemies.forEach(e=>updateEnemy(e,dt));}
  for(const ch of chests){if(ch.opening){ch.openAnim=Math.min(1,(ch.openAnim||0)+dt/.52);if(ch.openAnim>=1)ch.opening=false;}}
  for(let i=hazards.length-1;i>=0;i--){const h=hazards[i];if(h.scene!==scene)continue;h.life-=dt;h.age=(h.age||0)+dt;
    if(h.kind==='projectile'){
      h.x+=h.vx*dt;h.y+=h.vy*dt;let remove=false;
      for(const p of players){if(p.hp<=0)continue;if(dist(p,h)<h.r+p.r){if(p.inv>0){registerPerfectDodge(p,h);}else{hurtPlayer(p,h.dmg);}remove=true;break;}}
      if(remove||h.life<=0){hazards.splice(i,1);continue;}
    }else if(h.life<=0){
      for(const p of players){if(p.hp<=0)continue;if(dist(p,h)<h.r+p.r){if(p.inv>0)registerPerfectDodge(p,h);else hurtPlayer(p,h.dmg);}}
      hazards.splice(i,1);continue;
    }
  }
  for(const f of effects){f.life-=dt;if(f.kind==='number'){f.y-=24*dt;f.drift=(f.drift||0)+dt;}else if(f.kind==='spark'){f.x+=f.vx*dt;f.y+=f.vy*dt;f.vx*=Math.pow(.08,dt);f.vy+=85*dt;}else if(f.kind==='trail'){f.size+=(f.strong?140:92)*dt;}else if(f.kind==='ring'){f.radius+=(f.strong?90:62)*dt;}else if(f.kind==='burst'){f.spin=(f.spin||0)+dt*7;}}
  effects=effects.filter(f=>f.life>0);loot.forEach(l=>l.t=(l.t||0)+dt);if(!onlineCoop.active){cleanupEnemies();processRespawns(dt);processVictory(dt);}
  if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)UI.toast.style.display='none'}if(questToastTimer>0){questToastTimer-=dt;if(questToastTimer<=0&&UI.questToast)UI.questToast.style.display='none'}
  const living=players.filter(p=>p.hp>0);const target=onlineCoop.active?(onlineLocalPlayer()||players[0]):(living.length?{x:living.reduce((s,p)=>s+p.x,0)/living.length,y:living.reduce((s,p)=>s+p.y,0)/living.length}:players[0]);const lerp=1-Math.exp(-CAMERA_SPEED*dt);camera.x+=(target.x-camera.x)*lerp;camera.y+=(target.y-camera.y)*lerp;clampCamera();
}

