// Sprite animation
// ---------------------------
function frameXY(frame){return {sx:(frame%SHEET_COLS)*SHEET_CELL,sy:Math.floor(frame/SHEET_COLS)*SHEET_CELL};}
function sequenceFrame(seq,speed,t){return seq[Math.floor(t*speed)%seq.length];}
function playerFrame(p){if(p.hp<=0)return 11;if(p.flash>.1&&p.inv>0)return 10;if(p.skillCd>4.5)return 9;if(p.dashCd>.16)return 8;if(p.attackCd>0){const max=p.combo===3?.44:.27,prog=1-p.attackCd/max;return prog<.33?5:prog<.7?6:7}if(p.state==='run')return sequenceFrame([0,1,2,3],8,p.anim);return sequenceFrame([0,1,2,1],3,p.anim)}
function enemyFrame(e){if(e.hp<=0)return 11;if(e.flash>.08)return 10;if(e.state==='aggro'&&e.cd<.8)return e.cd<.25?7:e.cd<.55?6:5;if(e.state==='idle')return sequenceFrame([0,1],2.4,e.anim);return sequenceFrame([0,1,2,3],7,e.anim)}
function drawSheetFrame(sheet,frame,sx,sy,size,flip=false,alpha=1,customCtx=ctx){const im=drawAssets[sheet];if(!im)return;const f=frameXY(frame);customCtx.save();customCtx.globalAlpha=alpha;customCtx.translate(Math.round(sx),Math.round(sy));if(flip)customCtx.scale(-1,1);customCtx.drawImage(im,f.sx,f.sy,SHEET_CELL,SHEET_CELL,Math.round(-size/2),Math.round(-size),Math.round(size),Math.round(size));customCtx.restore()}
function assetSize(key,w){const im=drawAssets[key];if(!im)return {w,h:w};const iw=im.width||im.naturalWidth||1,ih=im.height||im.naturalHeight||1;return {w,h:w*ih/iw};}
function drawAssetBottom(key,x,y,w,alpha=1){const im=drawAssets[key];if(!im)return;const sz=assetSize(key,w);const s=worldToScreen(x,y);ctx.save();ctx.globalAlpha=alpha;ctx.drawImage(im,Math.round(s.x-sz.w/2),Math.round(s.y-sz.h),Math.round(sz.w),Math.round(sz.h));ctx.restore();}
function drawOutlinedText(text,x,y,fill='#fff',size=12,align='center'){
  ctx.font=`bold ${size}px ui-monospace, monospace`;ctx.textAlign=align;ctx.textBaseline='alphabetic';ctx.lineWidth=3;ctx.strokeStyle='rgba(0,0,0,.88)';ctx.strokeText(text,Math.round(x),Math.round(y));ctx.fillStyle=fill;ctx.fillText(text,Math.round(x),Math.round(y));
}

