function villagePlazaInfo(x,y){
  if(!villagePlaza)return {strength:0,ring:0,core:0};
  const nx=(x-villagePlaza.x)/(villagePlaza.rx||1),ny=(y-villagePlaza.y)/(villagePlaza.ry||1),r=Math.hypot(nx,ny),strength=clamp(1-r,0,1);
  return {strength,ring:(r>.56&&r<.76)?1:0,core:r<.27?1:0,axis:Math.min(Math.abs(nx),Math.abs(ny))<.08&&r<.34?1:0};
}
function drawVillageCobble(tx,ty,s,screenH){
  if(!isPathTile(tx,ty)||isWaterTile(tx,ty))return;
  const x=tx*TILE_SIZE+TILE_SIZE/2,y=ty*TILE_SIZE+TILE_SIZE/2,strength=villageCobbleStrength(x,y),plaza=villagePlazaInfo(x,y),total=Math.max(strength,plaza.strength*.92);
  if(total<=.08)return;
  ctx.save();
  const rows=plaza.strength>.2?2:1;
  for(let i=0;i<rows;i++){
    const rw=8+Math.floor(tileHash(tx,ty,73+i*11)*7),rh=2;
    const px=Math.round(s.x+5+tileHash(tx,ty,75+i*11)*(TILE_SIZE-rw-10));
    const py=Math.round(s.y+screenH*(.38+i*.24));
    ctx.fillStyle=`rgba(118,114,106,${.18+.16*total})`;ctx.fillRect(px,py,rw,rh);
    ctx.fillStyle=`rgba(62,58,53,${.13+.10*total})`;ctx.fillRect(px,py+rh,rw,1);
  }
  ctx.restore();
}
function drawVillagePlazaOverlay(){ return; }
