function drawTerrainIdentity(){
  const b=currentWorldBounds(TILE_SIZE),base=tileLayers.ground;if(!base)return;
  const minX=clamp(Math.floor(b.l/TILE_SIZE),0,base.width-1),maxX=clamp(Math.ceil(b.r/TILE_SIZE),0,base.width-1),minY=clamp(Math.floor(b.t/TILE_SIZE),0,base.height-1),maxY=clamp(Math.ceil(b.b/TILE_SIZE),0,base.height-1),screenH=Math.ceil(TILE_SIZE*PROJECTION_Y);
  for(let ty=minY;ty<=maxY;ty++)for(let tx=minX;tx<=maxX;tx++){
    const s=worldToScreen(tx*TILE_SIZE,ty*TILE_SIZE);
    if(isWaterTile(tx,ty)){drawWaterEdge(tx,ty,s,screenH);if(((tx+ty)&1)===0)drawWaterAccent(tx,ty,s,screenH);continue;}
    if(isPathTile(tx,ty)){drawPathEdge(tx,ty,s,screenH);drawVillageCobble(tx,ty,s,screenH);continue;}
    drawGroundMicroDetail(tx,ty,s,screenH);
    if(((tx*3+ty*5)&3)===0)drawShoreReeds(tx,ty,s,screenH);
  }
}
