  if(btnPotion)btnPotion.onclick=()=>{if(onlineCoop.active){setMessage('Online: las pociones todavía están desactivadas hasta sincronizar consumibles.');return;} const p=players&&players[0]; if(p&&typeof usePotion==='function')usePotion(p); };
  if(btnMenu)btnMenu.onclick=()=>returnToMainMenu();
  const closeInventoryBtn=byId('closeInventory'), closeQuestBtn=byId('closeQuest'), closeSkillsBtn=byId('closeSkills'), closeShopBtn=byId('closeShop');
  if(closeInventoryBtn)closeInventoryBtn.onclick=()=>closeOverlay();
  if(closeQuestBtn)closeQuestBtn.onclick=()=>closeOverlay();
  if(closeSkillsBtn)closeSkillsBtn.onclick=()=>closeOverlay();
  if(closeShopBtn)closeShopBtn.onclick=()=>closeOverlay();
  const tabP1=byId('tabP1'), tabP2=byId('tabP2');
  if(tabP1)tabP1.onclick=()=>openInventory(1);
  if(tabP2)tabP2.onclick=()=>players&&players.length>1&&openInventory(2);
