// Beta 0.47.2 — robust PC/online input binding
function bindGameplayKeyboard(){
  const movementCodes=new Set(['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight']);
  const actionCodes=new Set(['KeyF','KeyG','KeyH','KeyR','KeyE','KeyJ','KeyK','KeyL']);
  window.addEventListener('keydown',e=>{
    const tag=(e.target&&e.target.tagName)||'';
    if(tag==='INPUT'||tag==='TEXTAREA'||tag==='SELECT'||e.target?.isContentEditable)return;
    // Menus have their own keyboard behavior. Only feed gameplay while the game screen is active.
    if(!UI.start.classList.contains('hidden'))return;
    if(movementCodes.has(e.code)||actionCodes.has(e.code)){
      keys[e.code]=true;
      if(movementCodes.has(e.code)||['KeyF','KeyG','KeyH','KeyJ','KeyK','KeyL'].includes(e.code))e.preventDefault();
    }
    const actionMap={KeyF:'attack',KeyG:'dash',KeyH:'skill',KeyL:'attack',KeyK:'dash',KeyJ:'skill'};
    if(actionMap[e.code]){
      keys[e.code]=false;
      if(!e.repeat&&!overlay){const secondary=['KeyL','KeyK','KeyJ'].includes(e.code);const p=onlineCoop.active?(secondary?null:onlineLocalPlayer()):players[secondary?1:0];if(p){if(actionMap[e.code]==='attack')attack(p);else if(actionMap[e.code]==='dash')dash(p);else useSkill(p);}}
      e.preventDefault();return;
    }
    if(e.code==='KeyR'&&!e.repeat){
      const p=onlineCoop.active?onlineLocalPlayer():(players[0]||null);
      if(p)usePotion(p);
      keys.KeyR=false;e.preventDefault();
    }
    if(e.code==='KeyE'&&!e.repeat){interact();keys.KeyE=false;e.preventDefault();}
  },{passive:false});
  window.addEventListener('keyup',e=>{if(e.code in keys)keys[e.code]=false;});
  window.addEventListener('blur',()=>{for(const k of Object.keys(keys))keys[k]=false;resetTouchMove();});
}

